	return latestMid;
};

Messaging.canMessageUser = async (uid, toUid) => {
	if (meta.config.disableChat || uid <= 0) {
		throw new Error('[[error:chat-disabled]]');
	}

	if (parseInt(uid, 10) === parseInt(toUid, 10)) {
		throw new Error('[[error:cant-chat-with-yourself]]');
	}
	const [exists, isTargetPrivileged, canChat, canChatWithPrivileged] = await Promise.all([
		user.exists(toUid),
		user.isPrivileged(toUid),
		privileges.global.can('chat', uid),
		privileges.global.can('chat:privileged', uid),
		checkReputation(uid),
	]);

	if (!exists) {
		throw new Error('[[error:no-user]]');
	}

	if (!canChat && !(canChatWithPrivileged && isTargetPrivileged)) {
		throw new Error('[[error:no-privileges]]');
	}

	const [settings, isAdmin, isModerator, isFollowing, isBlocked] = await Promise.all([
		user.getSettings(toUid),
		user.isAdministrator(uid),
		user.isModeratorOfAnyCategory(uid),
		user.isFollowing(toUid, uid),
		user.blocks.is(uid, toUid),
	]);

	if (isBlocked) {
		throw new Error('[[error:chat-user-blocked]]');
	}
	if (settings.restrictChat && !isAdmin && !isModerator && !isFollowing) {
		throw new Error('[[error:chat-restricted]]');
	}

	await plugins.hooks.fire('static:messaging.canMessageUser', {
		uid: uid,
		toUid: toUid,
	});
};

Messaging.canMessageRoom = async (uid, roomId) => {
	if (meta.config.disableChat || uid <= 0) {
		throw new Error('[[error:chat-disabled]]');
	}

	const [roomData, inRoom, canChat] = await Promise.all([
		Messaging.getRoomData(roomId),
		Messaging.isUserInRoom(uid, roomId),
		privileges.global.can(['chat', 'chat:privileged'], uid),
		checkReputation(uid),
		user.checkMuted(uid),
	]);
	if (!roomData) {
		throw new Error('[[error:no-room]]');
	}

	if (!inRoom) {
		throw new Error('[[error:not-in-room]]');
	}

	if (!canChat.includes(true)) {
		throw new Error('[[error:no-privileges]]');
	}

	await plugins.hooks.fire('static:messaging.canMessageRoom', {
		uid: uid,
		roomId: roomId,
	});
};
'use strict';

const db = require('../../database');
const batch = require('../../batch');


module.exports = {
	name: 'Set "followercount" on each topic object',
	timestamp: Date.UTC(2025, 3, 15),
	method: async function () {
		const { progress } = this;

		progress.total = await db.sortedSetCard('topics:tid');

		await batch.processSortedSet('topics:tid', async (tids) => {
			const keys = tids.map(tid => `tid:${tid}:followers`);
			const followerCounts = await db.setsCount(keys);

			const bulkSet = [];

			followerCounts.forEach((count, idx) => {
				const tid = tids[idx];
				if (count > 0) {
					bulkSet.push([`topic:${tid}`, {followercount: count}]);
				}
			});

			await db.setObjectBulk(bulkSet);

			progress.incr(tids.length);
		}, {
			batch: 500,
		});
	},
};

'use strict';

const router = require('express').Router();
const middleware = require('../../middleware');
const controllers = require('../../controllers');
const routeHelpers = require('../helpers');

const { setupApiRoute } = routeHelpers;

// eslint-disable-next-line no-unused-vars
function guestRoutes() {
	// like registration, login...
}

function authenticatedRoutes() {
	const middlewares = [middleware.ensureLoggedIn];

	setupApiRoute(router, 'post', '/', [...middlewares, middleware.checkRequired.bind(null, ['username'])], controllers.write.users.create);
	setupApiRoute(router, 'delete', '/', [...middlewares, middleware.checkRequired.bind(null, ['uids'])], controllers.write.users.deleteMany);

	setupApiRoute(router, 'head', '/:uid', [middleware.assert.user], controllers.write.users.exists);
	setupApiRoute(router, 'get', '/:uid', [...middlewares, middleware.assert.user], controllers.write.users.get);
	setupApiRoute(router, 'put', '/:uid', [...middlewares, middleware.assert.user], controllers.write.users.update);
